import type { RunnerToControlPlane, SessionSnapshot } from "@wollipog/protocol";
import type { DurableCommandStore, DurableCommandReceipt } from "./durable-command-store.js";
import type { SessionCommandReceiptStore, SessionCommandInvocationReceipt } from "./session-command-receipt-store.js";
import { ProcessingWindow, RUNNER_WINDOW_FRAMES } from "./processing-window.js";

/** Queue overlays are regenerated by the acknowledged inventory. Replaying their older outbox
 * copies first adds a second inventory and can overwrite newer state. Other frames retain FIFO. */
export function projectReconnectOutboxMessage<T extends { type: string }, U>(
  message: T, paced: boolean, project: (message: T) => U | null,
): U | null {
  return paced && message.type === "session_queue" ? null : project(message);
}

interface ReconnectSource {
  republishSessionIds(): string[];
  republishSessionSnapshot(id: string): SessionSnapshot | null | undefined;
  republishSessionQueue(id: string): Extract<RunnerToControlPlane, { type: "session_queue" }> | null;
}

export function durableUpdateMessage(receipt: DurableCommandReceipt): Extract<RunnerToControlPlane, { type: "durable_session_command_update" }> {
  return {
    type: "durable_session_command_update",
    commandId: receipt.commandId, sessionId: receipt.sessionId, state: receipt.state, revision: receipt.revision,
    ...(receipt.error ? { error: receipt.error } : {}),
    ...(receipt.code ? { code: receipt.code } : {}),
    ...(receipt.userEventSeq !== undefined ? { userEventSeq: receipt.userEventSeq } : {}),
  };
}

export function sessionCommandUpdateMessage(receipt: SessionCommandInvocationReceipt): Extract<RunnerToControlPlane, { type: "session_command_invocation_update" }> {
  return {
    type: "session_command_invocation_update",
    invocationId: receipt.invocationId, submissionId: receipt.submissionId,
    sessionId: receipt.sessionId, state: receipt.state, revision: receipt.revision,
    ...(receipt.error ? { error: receipt.error } : {}),
    ...(receipt.code ? { code: receipt.code } : {}),
    ...(receipt.userEventSeq !== undefined ? { userEventSeq: receipt.userEventSeq } : {}),
  };
}

export interface ReconnectReceipts {
  durable: Pick<DurableCommandStore, "recentUpdateIds" | "recentUpdate">;
  invocations: Pick<SessionCommandReceiptStore, "recentUpdateIds" | "recentUpdate">;
}

/** Share processing credits across all regenerable inventories. Keep runtime frames consecutive
 * for grouped commits. Live sends stay immediate and no inventory caches state over a yield. */
export function republishReconnectState(
  source: ReconnectSource,
  project: (message: RunnerToControlPlane) => RunnerToControlPlane | null,
  write: (wire: string) => void,
  fail: () => void,
  diagnostic: ConstructorParameters<typeof ProcessingWindow>[4],
  receipts?: ReconnectReceipts,
): ProcessingWindow {
  const ids = source.republishSessionIds();
  const work: string[] = [];
  for (let offset = 0; offset < ids.length; offset += RUNNER_WINDOW_FRAMES) {
    const batch = ids.slice(offset, offset + RUNNER_WINDOW_FRAMES);
    work.push(...batch.map((id) => `runtime:${id}`), ...batch.map((id) => `queue:${id}`));
  }
  if (receipts) {
    work.push(...receipts.durable.recentUpdateIds().map((id) => `durable:${id}`),
      ...receipts.invocations.recentUpdateIds().map((id) => `invocation:${id}`));
  }
  return new ProcessingWindow(work, (key) => {
    let message: RunnerToControlPlane | null;
    if (key.startsWith("runtime:")) {
      const snapshot = source.republishSessionSnapshot(key.slice(8));
      message = snapshot ? { type: "session_runtime_updated", snapshot } : null;
    } else if (key.startsWith("durable:")) {
      const receipt = receipts!.durable.recentUpdate(key.slice(8));
      message = receipt ? durableUpdateMessage(receipt) : null;
    } else if (key.startsWith("invocation:")) {
      const receipt = receipts!.invocations.recentUpdate(key.slice(11));
      message = receipt ? sessionCommandUpdateMessage(receipt) : null;
    } else {
      message = source.republishSessionQueue(key.slice(6));
    }
    const projected = message && project(message);
    return projected ? JSON.stringify(projected) : null;
  }, write, fail, diagnostic);
}
